import * as THREE from 'three';

const $ = (s) => document.querySelector(s);
const clamp = (n, a, b) => Math.max(a, Math.min(b, n));
const saveKey = 'everlife-harborlight-v1';
const defaultState = {name:'Alex Morgan',age:22,day:1,hour:8,minute:24,money:1250,hunger:78,thirst:86,energy:92,mood:74,health:100,hygiene:81,career:'Between chapters',jobLevel:0,home:'A room at the Seabreeze Inn',partner:'',friends:0,married:false,children:0,relationships:{},events:['Moved to Harborlight, a place full of possibility.'],tasks:0,weather:'CLEAR SKIES',x:0,z:0};
let state; try { state={...defaultState,...JSON.parse(localStorage.getItem(saveKey)||'{}')}; } catch { state={...defaultState}; }
let scene,camera,renderer,player,clock,ambient,sun,weatherGroup,firstPerson=false,walkTime=0,toastTimer,gameReady=false,nearbyPlace=null,modalMode='',movement={x:0,z:0},joystick={x:0,y:0};
const npcs=[],places=[],keys=new Set();
const material=(color,roughness=.85)=>new THREE.MeshStandardMaterial({color,roughness});
const mats={grass:material('#87a47c'),path:material('#d1c6a7'),road:material('#737a72'),stripe:material('#e5dfc6'),water:material('#6eafb2',.34),leaf:material('#62896e'),leaf2:material('#89a47a'),trunk:material('#795b43'),white:material('#eadfce'),dark:material('#384746'),window: new THREE.MeshStandardMaterial({color:'#a9d4ce',roughness:.28,metalness:.08}),skin:material('#d3a27e'),shirt:material('#d57859'),pants:material('#385260'),roof:material('#a86950'),roof2:material('#c78a60'),gold:material('#edcc88')};
function box(parent,x,y,z,w,h,d,mat,cast=true){const o=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),mat);o.position.set(x,y,z);o.castShadow=cast;o.receiveShadow=true;parent.add(o);return o;}
function cylinder(parent,x,y,z,r1,r2,h,mat,seg=9){const o=new THREE.Mesh(new THREE.CylinderGeometry(r1,r2,h,seg),mat);o.position.set(x,y,z);o.castShadow=true;o.receiveShadow=true;parent.add(o);return o;}
function makeBuilding(x,z,w,d,h,wall,roofColor,name,kind='home'){
 const g=new THREE.Group();g.position.set(x,0,z);scene.add(g);box(g,0,h/2,0,w,h,d,material(wall));
 const roof=new THREE.Mesh(new THREE.ConeGeometry(Math.max(w,d)*.78,h*.32,4),material(roofColor));roof.position.y=h+h*.1;roof.rotation.y=Math.PI/4;roof.scale.z=d/Math.max(w,d);roof.castShadow=true;g.add(roof);
 const front=z<0?1:-1;for(let i=-1;i<=1;i++){if(Math.abs(i*w*.27)<w*.36)box(g,i*w*.27,h*.58,front*(d/2+.011),w*.14,h*.19,.025,mats.window,false);}
 box(g,0,.62,front*(d/2+.035),.68,1.24,.09,material('#92684d'));
 if(kind==='shop'){const awning=box(g,0,h*.66,front*(d/2+.14),w*.86,.34,.3,material('#e6dfc9'));awning.position.y=h*.66;box(g,0,h*.86,front*(d/2+.17),w*.75,.18,.08,material('#41675d'));}
 if(name){const sign=box(g,0,h*.82,front*(d/2+.15),Math.min(w*.8,3.8),.42,.09,material(kind==='shop'?'#345c50':'#52665a'),false);sign.position.y=h*.81;}
 g.userData={name,kind,x,z};places.push(g);return g;
}
function makeTree(x,z,scale=1){const g=new THREE.Group();g.position.set(x,0,z);scene.add(g);cylinder(g,0,.7,0,.17,.22,1.4,mats.trunk,7);const crown=new THREE.Mesh(new THREE.IcosahedronGeometry(.82,1),Math.random()>.5?mats.leaf:mats.leaf2);crown.position.y=1.75;crown.scale.set(scale,scale*1.05,scale);crown.castShadow=true;g.add(crown);const crown2=new THREE.Mesh(new THREE.IcosahedronGeometry(.53,1),mats.leaf);crown2.position.set(.35,2.1,.08);crown2.castShadow=true;g.add(crown2);}
function createWorld(){
 scene=new THREE.Scene();scene.background=new THREE.Color('#a9c7c2');scene.fog=new THREE.Fog('#a9c7c2',36,125);
 camera=new THREE.PerspectiveCamera(48,innerWidth/innerHeight,.1,180);
 renderer=new THREE.WebGLRenderer({canvas:$('#world'),antialias:false,powerPreference:'low-power'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.05;
 ambient=new THREE.HemisphereLight('#e5f4e3','#48604e',2.05);scene.add(ambient);sun=new THREE.DirectionalLight('#fff0d4',2.7);sun.position.set(-18,34,8);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);sun.shadow.camera.left=-28;sun.shadow.camera.right=28;sun.shadow.camera.top=28;sun.shadow.camera.bottom=-28;scene.add(sun);scene.add(sun.target);
 const ground=new THREE.Mesh(new THREE.PlaneGeometry(150,150),mats.grass);ground.rotation.x=-Math.PI/2;ground.position.y=-.04;ground.receiveShadow=true;scene.add(ground);
 // The main street and green, framed as a walkable little coastal neighborhood.
 box(scene,0,.01,8,90,.08,9,mats.road,false);box(scene,-2,.055,8,90,.012,.12,mats.stripe,false);box(scene,0,.12,2,38,.22,2.4,mats.path,false);
 box(scene,-28,.02,-28,28,.08,90,mats.water,false);for(let i=0;i<5;i++){const wave=new THREE.Mesh(new THREE.TorusGeometry(8+i*2,.035,3,42),new THREE.MeshBasicMaterial({color:'#c7e1d5',transparent:true,opacity:.18}));wave.rotation.x=Math.PI/2;wave.position.set(-28,.08,-20);scene.add(wave);}
 // Seabreeze Commons plaza, sidewalk and a pocket park.
 box(scene,0,.02,-5,24,.1,17,material('#a7ae8c'),false);box(scene,0,.085,-5,18,.08,12,material('#b5b28e'),false);
 for(let x=-7;x<=7;x+=3.5)for(let z=-9;z<=-1;z+=3.2)if(Math.hypot(x,z+5)>4)makeTree(x,z,.72+Math.random()*.23);
 // Locally varied homes and recognizable places.
 makeBuilding(-10,-15,6,5,4.4,'#e1c4a0','#b56e50','Seabreeze Inn','home');
 makeBuilding(0,-16,6.6,5,4.8,'#d7e3cf','#627e68','','home');
 makeBuilding(10,-15,6,5,4.4,'#dfc4a7','#be865b','Harborlight Café','cafe');
 makeBuilding(-12,-27,7,5.8,5.5,'#e2d7bd','#57796f','Market','shop');
 makeBuilding(2,-28,7,6,5.1,'#e7d2ad','#a96c55','Harbor Clinic','hospital');
 makeBuilding(14,-27,7.5,6.3,5.3,'#d6e0d1','#688171','Studio North','work');
 makeBuilding(-5,23,9,7,5.5,'#e3d4b8','#a77a57','','home');makeBuilding(10,25,8,6,4.8,'#d7e3d5','#627e69','Village homes','home');
 // A distant wooded hillside gives the open world a horizon.
 for(let i=0;i<22;i++){let x=-34+Math.random()*70,z=-42-Math.random()*16;const hill=new THREE.Mesh(new THREE.ConeGeometry(5+Math.random()*6,9+Math.random()*10,7),material(i%2?'#748e78':'#829a7c'));hill.position.set(x,3+Math.random()*3,z);hill.rotation.y=Math.random()*6;scene.add(hill);}
 for(let i=0;i<38;i++){const x=-37+Math.random()*75,z=-43+Math.random()*82;if(Math.abs(x)<17&&z>-32&&z<31)continue;if(x<-21&&z<-12)continue;makeTree(x,z,.7+Math.random()*.5);}
 createPlayer();createNPCs();createWeather();
}
function createPlayer(){player=new THREE.Group();scene.add(player);player.position.set(Number(state.x)||0,0,Number(state.z)||0);const skin=material('#c58e6b'),hair=material('#4e382f'),top=material('#dd8464'),pants=material('#405b67');
 const body=new THREE.Group();player.add(body);player.userData.body=body;
 const torso= new THREE.Mesh(new THREE.CapsuleGeometry(.3,.54,3,7),top);torso.position.y=1.12;torso.castShadow=true;body.add(torso);
 const head=new THREE.Mesh(new THREE.SphereGeometry(.25,10,8),skin);head.position.y=1.88;head.castShadow=true;body.add(head);
 const haircap=new THREE.Mesh(new THREE.SphereGeometry(.26,9,6,0,Math.PI*2,0,Math.PI*.56),hair);haircap.position.y=1.99;body.add(haircap);
 const legs=[];for(const x of [-.14,.14]){const leg=new THREE.Mesh(new THREE.CapsuleGeometry(.115,.47,2,6),pants);leg.position.set(x,.47,0);leg.castShadow=true;body.add(leg);legs.push(leg);}player.userData.legs=legs;
 for(const x of [-.38,.38]){const arm=new THREE.Mesh(new THREE.CapsuleGeometry(.09,.47,2,6),skin);arm.position.set(x,1.18,0);arm.rotation.z=x<0?-.12:.12;arm.castShadow=true;body.add(arm);}
}
function createNPCs(){const names=[['Maya','F'],['Noah','M'],['Jules','X'],['Sam','F'],['Eli','M'],['Riley','X']];const colors=['#819cb0','#b78ca7','#d7ad66','#72a68c','#be7762','#8392bf'];
 names.forEach(([name,gender],i)=>{const g=new THREE.Group();g.position.set(-8+i*3.1,-.0,-2+(i%2)*2.1);scene.add(g);const outfit=material(colors[i]),skin=material(i%2?'#b98164':'#d6a27d'),hair=material(['#3b302b','#563a2d','#292a34'][i%3]);const torso=new THREE.Mesh(new THREE.CapsuleGeometry(.26,.5,3,7),outfit);torso.position.y=1.05;torso.castShadow=true;g.add(torso);const head=new THREE.Mesh(new THREE.SphereGeometry(.23,9,7),skin);head.position.y=1.79;head.castShadow=true;g.add(head);const cap=new THREE.Mesh(new THREE.SphereGeometry(.24,8,6,0,Math.PI*2,0,Math.PI*.56),hair);cap.position.y=1.9;g.add(cap);for(const x of [-.13,.13]){const l=new THREE.Mesh(new THREE.CapsuleGeometry(.105,.4,2,6),mats.pants);l.position.set(x,.42,0);l.castShadow=true;g.add(l);}npcs.push({group:g,name,gender,index:i,baseX:g.position.x,baseZ:g.position.z,phase:Math.random()*6,patience:0});});}
function createWeather(){weatherGroup=new THREE.Group();scene.add(weatherGroup);for(let i=0;i<190;i++){const drop=new THREE.Mesh(new THREE.BoxGeometry(.025,.34,.025),new THREE.MeshBasicMaterial({color:'#c8e8ec',transparent:true,opacity:.62}));drop.position.set((Math.random()-.5)*60,Math.random()*25,(Math.random()-.5)*60);weatherGroup.add(drop);}}

