function createWeather(){weatherGroup=new THREE.Group();scene.add(weatherGroup);for(let i=0;i<190;i++){const drop=new THREE.Mesh(new THREE.BoxGeometry(.025,.34,.025),new THREE.MeshBasicMaterial({color:'#c8e8ec',transparent:true,opacity:.62}));drop.position.set((Math.random()-.5)*60,Math.random()*25,(Math.random()-.5)*60);weatherGroup.add(drop);}}
function persist(){state.x=player.position.x;state.z=player.position.z;localStorage.setItem(saveKey,JSON.stringify(state));$('#saveBtn').classList.add('saved');setTimeout(()=>$('#saveBtn').classList.remove('saved'),900);}
function showToast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2500);}
function addEvent(text){state.events.unshift(text);state.events=state.events.slice(0,12);}
function changeStat(stat,amount){state[stat]=clamp(state[stat]+amount,0,100);}
function advance(minutes, fatigue=0){const total=state.hour*60+state.minute+minutes;state.day+=Math.floor(total/1440);state.hour=Math.floor(total/60)%24;state.minute=total%60;changeStat('hunger',-minutes*.024);changeStat('thirst',-minutes*.033);changeStat('energy',-minutes*.014-fatigue);if(state.hunger<15||state.thirst<12)changeStat('health',-Math.max(1,minutes*.01));renderUI();}
function renderUI(){
 const pct=(id,value)=>{const n=Math.round(value);$(id).textContent=`${n}%`;$(id.replace('Text','Bar')).style.width=`${n}%`;};
 pct('#hungerText',state.hunger);pct('#thirstText',state.thirst);pct('#energyText',state.energy);pct('#moodText',state.mood);pct('#healthText',state.health);
 $('#playerName').textContent=state.name;$('#avatarInitial').textContent=(state.name.split(' ').map(s=>s[0]).join('').slice(0,1)||'A').toUpperCase();$('#lifeStage').textContent=`${stageName()} · DAY ${state.day}`;
 $('#moneyText').textContent=`$${Math.floor(state.money).toLocaleString()}`;
 const h=state.hour%12||12,ampm=state.hour>=12?'PM':'AM';$('#clockTime').innerHTML=`${String(h).padStart(2,'0')}:${String(state.minute).padStart(2,'0')} <span>${ampm}</span>`;
 $('#dateLabel').textContent=`${['APR','APR','MAY','MAY','JUN'][Math.floor((state.day-1)/30)%5]} ${String((state.day-1)%30+1).padStart(2,'0')}, 2025`;
 $('#weatherLabel').textContent=state.weather;$('#weatherLabel').style.color=state.weather==='RAIN SHOWERS'?'#c3e7ed':'';
 const hasMet=state.friends>0;$('#objectiveText').textContent=hasMet?'Pick something that feels like you':'Say hello to someone new';$('#objectiveCount').textContent=hasMet?'1 / 1':'0 / 1';$('#objectiveCheck').textContent=hasMet?'✓':'○';
 const goal=state.jobLevel?'Build a life you love':'Find your rhythm';$('#goalTitle').textContent=goal;$('#goalText').textContent=state.partner?`You and ${state.partner} are writing your story together.`:state.jobLevel?`${state.career} · Level ${state.jobLevel}. The next chapter is yours.`:'Explore Harborlight and decide what your first day will look like.';
 const pos=player?player.position:new THREE.Vector3();$('#nearbyText').textContent=nearbyPlace?.name||'Seabreeze Commons';$('#nearbyDistance').textContent=`${Math.round(Math.max(0,Math.hypot(pos.x,pos.z+5)*1.5))} m`;
}
function stageName(){return state.age<26?'YOUNG ADULT':state.age<40?'ADULT':state.age<60?'ESTABLISHED':'LEGACY';}
function openModal(kicker,title,description,options,extra=''){
 modalMode=title;const content=$('#modalContent');content.innerHTML=`<span class="modal-kicker">${kicker}</span><h2>${title}</h2><p>${description}</p>${extra}<div class="option-list">${options.map((o,i)=>`<button class="option" data-choice="${i}"><span class="option-emoji">${o.icon||'✦'}</span><span class="option-copy"><strong>${o.title}</strong><small>${o.note||''}</small></span>${o.price?`<span class="option-price">${o.price}</span>`:''}</button>`).join('')}</div>`;
 content.querySelectorAll('[data-choice]').forEach((el)=>el.addEventListener('click',()=>options[Number(el.dataset.choice)].run()));$('#modalBackdrop').classList.add('open');
}
function closeModal(){$('#modalBackdrop').classList.remove('open');modalMode='';}
function action(actionName){
 if(actionName==='eat'){openModal('A LITTLE NOURISHMENT','Take a moment to eat','A good meal will bring your energy back. A small ritual can change the shape of the day.',[
 {icon:'🥐',title:'Fresh pastry',note:'A little treat from the café',price:'$8',run:()=>{if(state.money<8)return showToast('Not quite enough in your wallet.');state.money-=8;changeStat('hunger',24);changeStat('mood',3);advance(12);actDone('A fresh pastry and a deep breath.');}},
 {icon:'🥗',title:'Market lunch',note:'A wholesome meal for the road',price:'$18',run:()=>{if(state.money<18)return showToast('Not quite enough in your wallet.');state.money-=18;changeStat('hunger',43);changeStat('health',3);advance(22);actDone('That was exactly what you needed.');}},
 {icon:'🍲',title:'Cook something at home',note:'A comforting meal, no cost',run:()=>{changeStat('hunger',30);changeStat('mood',2);advance(30);actDone('You made a simple, comforting meal.');}}
 ]);}
 if(actionName==='drink'){if(state.money<3)return showToast('You need a few dollars for a drink.');state.money-=3;changeStat('thirst',34);advance(3);actDone('A cool drink. You feel more like yourself.');}
 if(actionName==='social')openSocial();
 if(actionName==='career')openCareer();
 if(actionName==='home')openHome();
 if(actionName==='phone')openLife();
}
function actDone(message){closeModal();renderUI();persist();showToast(message);}
function openSocial(){const nearby=npcs.filter(n=>player.position.distanceTo(n.group.position)<12).sort((a,b)=>player.position.distanceTo(a.group.position)-player.position.distanceTo(b.group.position))[0];const person=nearby||npcs[Math.floor(Math.random()*npcs.length)];const score=state.relationships[person.name]||0;const rel=score>=5?'close friend':score>=2?'good friend':score>0?'getting to know you':'new face';
 const opts=[{icon:'☀',title:`Say hello to ${person.name}`,note:`A friendly conversation · ${rel}`,run:()=>{state.relationships[person.name]=(state.relationships[person.name]||0)+1;state.friends=Math.max(state.friends,Object.values(state.relationships).filter(v=>v>0).length);changeStat('mood',9);changeStat('energy',-3);advance(14,2);addEvent(`Met ${person.name} around Seabreeze Commons.`);actDone(`${person.name} smiles. It feels good to connect.`);}},
 {icon:'☕',title:'Invite them for coffee',note:'Share a little more of the afternoon',price:'$12',run:()=>{if(state.money<12)return showToast('You need $12 for coffee together.');state.money-=12;state.relationships[person.name]=(state.relationships[person.name]||0)+2;state.friends=Math.max(state.friends,Object.values(state.relationships).filter(v=>v>0).length);changeStat('mood',13);advance(38,5);addEvent(`Shared coffee with ${person.name}.`);if((state.relationships[person.name]||0)>=4&&!state.partner&&Math.random()>.45){state.partner=person.name;addEvent(`A spark with ${person.name} turned into something more.`);}actDone(`A lovely time with ${person.name}.`);}},
 {icon:'♡',title:score>=3?`Ask ${person.name} on a date`:'Get to know someone first',note:score>=3?'A little romance could be in the air.':'Build a connection with a few conversations.',run:()=>{if(score<3)return showToast(`${person.name} would love to know you a little better first.`);state.partner=person.name;state.relationships[person.name]+=1;changeStat('mood',17);advance(60,8);addEvent(`A memorable first date with ${person.name}.`);actDone(`${person.name} said yes. Something lovely is beginning.`);}}];
 openModal('PEOPLE MAKE A PLACE','A familiar face',`${person.name} is nearby. The best stories often start with a small hello.`,opts,`<div class="stat-chips"><span class="chip">♡ ${state.friends} friends</span><span class="chip">${state.partner?'♥ '+state.partner:'Open to connection'}</span></div>`);
}

