function openCareer(){const job=state.jobLevel>0;const options=job?[{icon:'▣',title:`Work a shift at ${state.career}`,note:'A steady shift, then the rest of the day is yours',price:'+ $110',run:()=>{state.money+=110+state.jobLevel*20;changeStat('energy',-25);changeStat('hunger',-13);changeStat('mood',-2);advance(240,15);if(Math.random()<.35){state.jobLevel++;addEvent(`A little recognition at work. Now level ${state.jobLevel}.`);}actDone('Shift complete. You earned an honest living.') }},{icon:'↗',title:'Ask for a promotion',note:'You have shown up. It is time to ask.',run:()=>{if(state.jobLevel<2)return showToast('A little more experience will help.');state.jobLevel++;actDone('Your manager sees your potential. Promotion earned!');}}]:[{icon:'☕',title:'Café host',note:'Meet neighbors and make a welcoming space',price:'$90 / shift',run:()=>{state.career='Café host';state.jobLevel=1;addEvent('Started a new chapter as a café host.');actDone('You got the job. Your first shift is tomorrow!')}},{icon:'✿',title:'Community gardener',note:'Work outside and care for the neighborhood',price:'$95 / shift',run:()=>{state.career='Community gardener';state.jobLevel=1;addEvent('Started a new chapter as a community gardener.');actDone('You got the job. Green things are ahead!')}},{icon:'✎',title:'Freelance illustrator',note:'Set your own pace and follow your creativity',price:'$70 / shift',run:()=>{state.career='Freelance illustrator';state.jobLevel=1;addEvent('Started a new chapter as a freelance illustrator.');actDone('Your first creative commission is yours!')}}];
