 openModal('THE PEOPLE YOU COME HOME TO',`${state.partner} & you`,'Love grows through the small, everyday things. This chapter is yours to shape.',options,`<div class="stat-chips"><span class="chip">♥ ${state.married?'Married':'Partners'}</span><span class="chip">♧ ${state.children} children</span></div>`);
}
function openProfile(){const current=state.name;openModal('A NEW CHAPTER','What should we call you?','Make the life feel like yours. You can always change this later.',[{icon:'✓',title:'Save my name',note:'Your life, your name',run:()=>{const v=$('#nameInput').value.trim();if(v)state.name=v;actDone(`Nice to meet you, ${state.name.split(' ')[0]}.`);}}],`<input id="nameInput" class="modal-input" maxlength="24" value="${current.replaceAll('"','&quot;')}" aria-label="Your name">`);}
function openPlace(place){
 const k=place.userData.kind,name=place.userData.name||'Harborlight';const opts=[];
 if(k==='cafe')opts.push({icon:'☕',title:'Settle in for a coffee',note:'A warm cup and a little people-watching',price:'$7',run:()=>{if(state.money<7)return showToast('A coffee costs $7.');state.money-=7;changeStat('thirst',18);changeStat('mood',7);advance(25,2);actDone('The café hum is comforting. You can stay a little longer.')}},{icon:'🥐',title:'Pick up a pastry',note:'Fresh from the oven',price:'$8',run:()=>{if(state.money<8)return showToast('A pastry costs $8.');state.money-=8;changeStat('hunger',24);advance(8);actDone('A fresh pastry for the walk.')}});
 if(k==='shop')opts.push({icon:'🛍',title:'Pick up groceries',note:'Stock the kitchen for the next few days',price:'$32',run:()=>{if(state.money<32)return showToast('You need $32 for groceries.');state.money-=32;changeStat('hunger',15);addEvent('Picked up groceries at the neighborhood market.');actDone('Your kitchen is stocked for the week.')}},{icon:'✿',title:'Buy a little something',note:'Flowers for the windowsill',price:'$15',run:()=>{if(state.money<15)return showToast('Flowers cost $15.');state.money-=15;changeStat('mood',8);actDone('A little color for your home.')}});
 if(k==='hospital')opts.push({icon:'✚',title:'Check in with the doctor',note:'Care for your health and get peace of mind',price:'$40',run:()=>{if(state.money<40)return showToast('A visit costs $40.');state.money-=40;state.health=100;changeStat('mood',3);advance(45,4);addEvent('A reassuring visit to Harbor Clinic.');actDone('The doctor says you are doing well.')}},{icon:'♧',title:'Pick up a prescription',note:'Feeling under the weather? Take care.',price:'$16',run:()=>{if(state.money<16)return showToast('Medication costs $16.');state.money-=16;changeStat('health',25);actDone('You have what you need to feel better.')}});
 if(k==='work')opts.push({icon:'▣',title:state.jobLevel?`Work at ${name}`:'Ask about work',note:state.jobLevel?'Your workplace is a familiar part of the day.':'A good place to start a career',run:()=>{if(!state.jobLevel){state.career='Studio assistant';state.jobLevel=1;addEvent('Started a new chapter as a studio assistant.');return actDone('They have a position for you. Welcome aboard!');}state.money+=130;changeStat('energy',-23);advance(240,15);actDone('A good shift at the studio. You earned $130.');}});
 opts.push({icon:'⌖',title:'Step outside',note:'The neighborhood is waiting for you',run:()=>{closeModal();showToast('Back out in Harborlight. Where to next?')}});
 openModal('A PLACE IN HARBORLIGHT',name,`Come in and take your time. Every corner of town has something going on.`,opts,`<div class="stat-chips"><span class="chip">${k==='cafe'?'☕ Café':k==='shop'?'▣ Market':k==='hospital'?'✚ Clinic':k==='work'?'✎ Workplace':'⌂ Home'}</span><span class="chip">Open today</span></div>`);
}
function interact(){if(nearbyPlace){openPlace(nearbyPlace);return;}const near=npcs.filter(n=>player.position.distanceTo(n.group.position)<4).sort((a,b)=>player.position.distanceTo(a.group.position)-player.position.distanceTo(b.group.position))[0];if(near){openSocial();return;}action('social');}
function findNearby(){let best=Infinity,found=null;for(const p of places){const dist=Math.hypot(player.position.x-p.userData.x,player.position.z-p.userData.z);if(dist<best){best=dist;found=p;}}nearbyPlace=best<12?found:null;
 const person=npcs.some(n=>player.position.distanceTo(n.group.position)<4);$('#promptText').textContent=nearbyPlace?`Visit ${nearbyPlace.userData.name||'neighborhood home'}`:person?'Meet someone nearby':'Meet a neighbor';$('#interactionPrompt').style.opacity='1';
 const marker=$('.pin-you');if(marker){marker.style.left=`${clamp(50+player.position.x*1.35,8,90)}%`;marker.style.top=`${clamp(52+player.position.z*.6,14,86)}%`;}
}
function toggleCamera(){firstPerson=!firstPerson;showToast(firstPerson?'First-person view':'Third-person view');}
function setWeather(){state.weather=state.weather==='CLEAR SKIES'?'RAIN SHOWERS':'CLEAR SKIES';const rainy=state.weather==='RAIN SHOWERS';weatherGroup.visible=rainy;scene.fog.color.set(rainy?'#829a9e':'#a9c7c2');scene.background.set(rainy?'#829a9e':'#a9c7c2');sun.intensity=rainy?1.15:2.7;showToast(rainy?'A little rain is moving through.':'The clouds are clearing.');renderUI();}
function updateTime(dt){if(!gameReady)return;state.minute+=dt*1.15;if(state.minute>=60){state.hour++;state.minute-=60;if(state.hour>=24){state.hour=0;state.day++;if(state.day%30===0){state.money-=75;addEvent('Monthly rent of $75 was paid.');}}renderUI();}if(Math.random()<dt*.0014)setWeather();const t=(state.hour+state.minute/60)/24;const daylight=Math.max(.24,Math.sin((t-.25)*Math.PI*2)*.52+.55);sun.intensity=(state.weather==='RAIN SHOWERS'?1.1:2.35)*daylight;ambient.intensity=.9+daylight*.7;}

